//! The JSON shapes of the four tools.
//!
//! These mirror the engine and core types rather than reusing them, because a
//! tool's input schema is part of what the model reads: it has to carry
//! descriptions, and it has to be generated by `schemars`, which the engine
//! types do not derive. Mirroring also pins the wire contract here, where it can
//! be changed deliberately, instead of letting a field added inside the engine
//! silently become part of a published schema.

use kompressor_core::RetrieveRange;
use kompressor_engine::messages::Protection;
use kompressor_engine::messages::{Message, MessageContent, MessageMeta, TextSlot};
use kompressor_engine::options::EngineOptionsPatch;
use kompressor_engine::types::{ForcedType, Mode};
use rmcp::ErrorData;
use schemars::JsonSchema;
use serde::{Deserialize, Serialize};

/// A compression mode, as a caller names it.
#[derive(Clone, Copy, Debug, PartialEq, Eq, Deserialize, Serialize, JsonSchema)]
#[serde(rename_all = "snake_case")]
pub enum WireMode {
    /// Elide and announce, but retain nothing. Nothing is retrievable
    /// afterwards, which is the right choice for a caller that cannot retrieve.
    Aggressive,
    /// Reversible-by-construction transforms only.
    Lossless,
    /// Elide, and stash every elision behind a `ref:k_...` handle this server
    /// can hand back.
    Recoverable,
}

impl From<WireMode> for Mode {
    fn from(mode: WireMode) -> Mode {
        match mode {
            WireMode::Aggressive => Mode::Aggressive,
            WireMode::Lossless => Mode::Lossless,
            WireMode::Recoverable => Mode::Recoverable,
        }
    }
}

/// A content type the caller asserts, bypassing detection.
#[derive(Clone, Copy, Debug, PartialEq, Eq, Deserialize, Serialize, JsonSchema)]
#[serde(rename_all = "snake_case")]
pub enum WireContentType {
    Json,
    Log,
    Text,
    Config,
}

impl From<WireContentType> for ForcedType {
    fn from(kind: WireContentType) -> ForcedType {
        match kind {
            WireContentType::Json => ForcedType::Json,
            WireContentType::Log => ForcedType::Log,
            WireContentType::Text => ForcedType::Text,
            WireContentType::Config => ForcedType::Config,
        }
    }
}

/// One independently compressible text run inside a block-structured message.
#[derive(Clone, Debug, Deserialize, Serialize, JsonSchema)]
pub struct WireSlot {
    /// The text of this block.
    pub text: String,
    /// Set when these exact bytes must survive, such as a prompt-cache
    /// breakpoint.
    #[serde(default)]
    pub protected: bool,
}

/// The body of a message.
///
/// A plain string, a list of text blocks, or `null` for content this engine
/// cannot read at all (an image, audio, a structured tool result).
#[derive(Clone, Debug, Deserialize, Serialize, JsonSchema)]
#[serde(untagged)]
pub enum WireContent {
    /// A plain string body.
    Text(String),
    /// Several text runs, compressed independently and written back in place.
    Blocks(Vec<WireSlot>),
    /// Nothing readable.
    Opaque,
}

/// What the caller knows about a message beyond its role and body.
#[derive(Clone, Debug, Default, Deserialize, Serialize, JsonSchema)]
pub struct WireMeta {
    /// This message is a prompt-cache breakpoint; its bytes are load-bearing.
    #[serde(default)]
    pub cache_control: bool,
    /// The caller asks that this message not be touched.
    #[serde(default)]
    pub protected: bool,
    /// The tool that produced this message, when it is a tool result.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub tool_name: Option<String>,
    /// The file the tool acted on, when it names one.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub file_path: Option<String>,
}

/// One conversation message.
#[derive(Clone, Debug, Deserialize, Serialize, JsonSchema)]
pub struct WireMessage {
    /// `system`, `user`, `assistant`, `tool`, or whatever the caller's API uses.
    pub role: String,
    /// The message body.
    pub content: WireContent,
    /// Optional per-message facts that change what may be compressed.
    #[serde(default)]
    pub meta: WireMeta,
}

impl From<WireMessage> for Message {
    fn from(message: WireMessage) -> Message {
        Message {
            role: message.role,
            content: match message.content {
                WireContent::Text(text) => MessageContent::Text(text),
                WireContent::Blocks(slots) => MessageContent::Blocks(
                    slots
                        .into_iter()
                        .map(|slot| TextSlot {
                            text: slot.text,
                            protected: slot.protected,
                            // The wire says *that* a slot is protected, not
                            // why, so the reason that cannot be wrong is the
                            // only honest one to invent on a caller's behalf.
                            protection: Protection::Always,
                        })
                        .collect(),
                ),
                WireContent::Opaque => MessageContent::Opaque,
            },
            meta: MessageMeta {
                cache_control: message.meta.cache_control,
                protected: message.meta.protected,
                tool_name: message.meta.tool_name,
                file_path: message.meta.file_path,
            },
        }
    }
}

impl From<Message> for WireMessage {
    fn from(message: Message) -> WireMessage {
        WireMessage {
            role: message.role,
            content: match message.content {
                MessageContent::Text(text) => WireContent::Text(text),
                MessageContent::Blocks(slots) => WireContent::Blocks(
                    slots
                        .into_iter()
                        .map(|slot| WireSlot {
                            text: slot.text,
                            protected: slot.protected,
                        })
                        .collect(),
                ),
                MessageContent::Opaque => WireContent::Opaque,
            },
            meta: WireMeta {
                cache_control: message.meta.cache_control,
                protected: message.meta.protected,
                tool_name: message.meta.tool_name,
                file_path: message.meta.file_path,
            },
        }
    }
}

/// Which part of a retained fragment to return.
///
/// Exactly one variant is given, as a single-key object, for example
/// `{"lines": {"start": 1, "end": 40}}`.
#[derive(Clone, Debug, Deserialize, Serialize, JsonSchema)]
#[serde(rename_all = "snake_case", deny_unknown_fields)]
pub enum WireRange {
    /// A 1-based inclusive line window, the way an editor addresses a file.
    Lines {
        /// First line to return, counting from 1.
        #[schemars(schema_with = "non_negative_integer")]
        start: usize,
        /// Last line to return, included.
        #[schemars(schema_with = "non_negative_integer")]
        end: usize,
    },
    /// An RFC 6901 pointer into a fragment that is JSON, such as `/3/items`.
    JsonPointer {
        /// The pointer, starting with `/`.
        pointer: String,
    },
    /// A character window, half-open and snapped to character boundaries.
    Chars {
        /// First character to return, counting from 0.
        #[schemars(schema_with = "non_negative_integer")]
        start: usize,
        /// One past the last character to return.
        #[schemars(schema_with = "non_negative_integer")]
        end: usize,
    },
    /// Lines containing a literal substring, with surrounding context lines.
    Grep {
        /// The literal to look for. Not a regular expression.
        pattern: String,
        /// How many lines of context to keep on each side of a match.
        #[serde(default = "default_context")]
        #[schemars(schema_with = "non_negative_integer")]
        context: usize,
    },
}

fn default_context() -> usize {
    2
}

impl From<WireRange> for RetrieveRange {
    fn from(range: WireRange) -> RetrieveRange {
        match range {
            WireRange::Lines { start, end } => RetrieveRange::Lines { start, end },
            WireRange::JsonPointer { pointer } => RetrieveRange::JsonPointer { pointer },
            WireRange::Chars { start, end } => RetrieveRange::Chars { start, end },
            WireRange::Grep { pattern, context } => RetrieveRange::Grep { pattern, context },
        }
    }
}

/// Arguments to `optscale_kompressor_retrieve`.
#[derive(Clone, Debug, Deserialize, Serialize, JsonSchema)]
pub struct RetrieveInput {
    /// The handle from the marker, `k_` followed by 12 url-safe characters. The
    /// leading `ref:` may be included or left off.
    #[serde(rename = "ref")]
    pub reference: String,
    /// Return only part of the fragment. Strongly preferred: everything returned
    /// is re-injected into your next request and billed again.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub range: Option<WireRange>,
}

/// A count, as JSON Schema can actually express one.
///
/// `schemars` renders a `usize` as `{"type": "integer", "format": "uint"}`, and
/// `uint` is not a JSON Schema format. Validators are required to ignore an
/// unknown format, so nothing breaks — but Claude Code says so out loud, once
/// per schema, on every session that lists these tools:
///
/// ```text
/// unknown format "uint" ignored in schema at path "#/properties/total_chars"
/// ```
///
/// That is noise in the one place a user is trying to read what went wrong, and
/// it doubles when the tool reaches a client twice. `minimum: 0` says the same
/// thing in the vocabulary the specification defines.
fn non_negative_integer(_: &mut schemars::SchemaGenerator) -> schemars::Schema {
    schemars::json_schema!({
        "type": "integer",
        "minimum": 0
    })
}

/// The result of `optscale_kompressor_retrieve`.
#[derive(Clone, Debug, Deserialize, Serialize, JsonSchema)]
pub struct RetrieveOutput {
    /// The fragment, or the part of it the range selected. Absent on a miss.
    #[serde(skip_serializing_if = "Option::is_none")]
    pub content: Option<String>,
    /// Whether the handle resolved.
    pub found: bool,
    /// The fragment was held and its retention window has since passed.
    pub expired: bool,
    /// A range was applied, so `content` is part of the fragment, not all of it.
    pub ranged: bool,
    /// Lines in the whole fragment, not in what was returned.
    #[schemars(schema_with = "non_negative_integer")]
    pub total_lines: usize,
    /// Characters in the whole fragment, not in what was returned.
    #[schemars(schema_with = "non_negative_integer")]
    pub total_chars: usize,
    /// The result hit the server's size cap and was cut. Narrow it with a range.
    pub truncated: bool,
    /// What to do instead, when something went wrong enough to say so: a miss
    /// that needs regenerating rather than inventing, or a range that selected
    /// nothing and should be widened or dropped. Absent when the retrieval
    /// returned what was asked for.
    #[serde(skip_serializing_if = "Option::is_none")]
    pub hint: Option<String>,
}

/// Arguments to `optscale_kompressor_compress`.
#[derive(Clone, Debug, Deserialize, Serialize, JsonSchema)]
pub struct CompressInput {
    /// The conversation to compress, oldest first.
    pub messages: Vec<WireMessage>,
    /// The model the conversation is bound for, recorded for attribution only.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub model: Option<String>,
    /// The provider the conversation is bound for, recorded for attribution
    /// only.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub provider: Option<String>,
    /// Compression mode. Defaults to `recoverable`, which keeps every elision
    /// fetchable through `optscale_kompressor_retrieve`. Pass `aggressive` if nothing in
    /// your loop will ever retrieve.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub mode: Option<WireMode>,
    /// Engine knobs for this request only, such as
    /// `{"min_compress_chars": 2048}`. An unknown key is rejected rather than
    /// ignored, so a typo cannot silently leave the default in place.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub options: Option<serde_json::Map<String, serde_json::Value>>,
}

/// Arguments to `optscale_kompressor_compress_raw`.
#[derive(Clone, Debug, Deserialize, Serialize, JsonSchema)]
pub struct CompressRawInput {
    /// The payload to compress.
    pub content: String,
    /// Skip detection and treat the payload as this kind of content.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub content_type: Option<WireContentType>,
    /// Compression mode. Defaults to `recoverable`.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub mode: Option<WireMode>,
    /// Engine knobs for this request only.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub options: Option<serde_json::Map<String, serde_json::Value>>,
}

/// Arguments to `optscale_kompressor_stats`.
#[derive(Clone, Debug, Deserialize, Serialize, JsonSchema)]
pub struct StatsInput {
    /// Start of the window, Unix milliseconds. Defaults to 24 hours ago.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub from: Option<i64>,
    /// End of the window, Unix milliseconds. Defaults to now.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub to: Option<i64>,
}

/// Turn a caller's `options` object into an engine patch.
///
/// The patch type lives in the engine and rejects unknown keys, so this is a
/// re-serialisation rather than a field-by-field mirror: a knob added to the
/// engine becomes available here without a second edit, and a knob removed stops
/// being accepted rather than being quietly dropped.
pub fn patch_from(
    options: Option<serde_json::Map<String, serde_json::Value>>,
    mode: Option<WireMode>,
) -> Result<Option<EngineOptionsPatch>, ErrorData> {
    if options.is_none() && mode.is_none() {
        return Ok(None);
    }
    let mut patch: EngineOptionsPatch = match options {
        Some(map) => serde_json::from_value(serde_json::Value::Object(map))
            .map_err(|error| ErrorData::invalid_params(format!("options: {error}"), None))?,
        None => EngineOptionsPatch::default(),
    };
    // An explicit `mode` argument is the documented spelling and wins over one
    // buried in `options`, so the two cannot disagree about what ran.
    if let Some(mode) = mode {
        patch.mode = Some(mode.into());
    }
    Ok(Some(patch))
}

/// Strip the `ref:` prefix a model may copy straight out of a marker.
///
/// The marker reads `[... 87 log lines omitted [ref:k_AbC123dEf456]]`, so the
/// most natural thing to paste is `ref:k_AbC123dEf456`. Refusing that would make
/// the tool fail on its own documented input.
pub fn normalize_handle(reference: &str) -> &str {
    let trimmed = reference.trim();
    trimmed.strip_prefix("ref:").unwrap_or(trimmed)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn a_handle_pasted_with_its_marker_prefix_is_accepted() {
        assert_eq!(normalize_handle("ref:k_AbC123dEf456"), "k_AbC123dEf456");
        assert_eq!(normalize_handle("  k_AbC123dEf456 "), "k_AbC123dEf456");
    }

    #[test]
    fn a_range_is_a_single_key_object_naming_the_variant() {
        let range: WireRange =
            serde_json::from_str(r#"{"json_pointer":{"pointer":"/3/items"}}"#).unwrap();
        assert!(matches!(range, WireRange::JsonPointer { .. }));
        let grep: WireRange = serde_json::from_str(r#"{"grep":{"pattern":"ERROR"}}"#).unwrap();
        match grep {
            WireRange::Grep { context, .. } => assert_eq!(context, 2, "context defaults"),
            other => panic!("expected grep, got {other:?}"),
        }
    }

    #[test]
    fn an_explicit_mode_beats_one_hidden_in_the_options_object() {
        let mut options = serde_json::Map::new();
        options.insert("mode".into(), serde_json::json!("aggressive"));
        let patch = patch_from(Some(options), Some(WireMode::Lossless))
            .unwrap()
            .unwrap();
        assert_eq!(patch.mode, Some(Mode::Lossless));
    }

    #[test]
    fn an_unknown_option_is_refused_rather_than_ignored() {
        let mut options = serde_json::Map::new();
        options.insert("min_compres_chars".into(), serde_json::json!(10));
        assert!(patch_from(Some(options), None).is_err());
    }

    #[test]
    fn a_message_survives_the_round_trip_through_the_wire_shape() {
        let original = Message {
            role: "tool".into(),
            content: MessageContent::Blocks(vec![TextSlot {
                text: "hello".into(),
                protected: true,
                protection: kompressor_engine::messages::Protection::Always,
            }]),
            meta: MessageMeta {
                cache_control: true,
                protected: false,
                tool_name: Some("Bash".into()),
                file_path: None,
            },
        };
        let back: Message = WireMessage::from(original.clone()).into();
        assert_eq!(back, original);
    }

    #[test]
    fn unreadable_content_is_carried_as_null_rather_than_dropped() {
        let message: WireMessage =
            serde_json::from_str(r#"{"role":"user","content":null}"#).unwrap();
        assert!(matches!(message.content, WireContent::Opaque));
        let engine: Message = message.into();
        assert!(engine.content.is_opaque());
    }
}
